const SCALE = 1;
const DENSITY = 2;
const DOT_SIZE = 1.4;

let canvas = null;
let ctx = null;
let particles = [];

let imgW = 0;
let imgH = 0;
let imgCx = 0;
let imgCy = 0;

let speaking = false;
let audioLevel = 0;
let pulseKick = 0;
let lastTs = 0;
let animStartTs = 0;
const BUILD_DURATION_MS = 2200;

let reactorX = 0;
let reactorY = 0;
let reactorR = 0;

let currentAvatarImage = null;

let rainCanvas = null;
let rainCtx = null;
let rainColumns = [];
let rainLastTs = 0;
const RAIN_FONT_PX = 16;
const RAIN_COLOR = { r: 109, g: 112, b: 112 };
const RAIN_BG = { r: 26, g: 25, b: 25 };
const RAIN_FADE_ALPHA = 0.08;
const RAIN_CHARS = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ@$%#*+-=<>[]{}()アイウエオカキクケコサシスセソタチツテトナニヌネノ";

function clamp(v, min, max) {
	return Math.max(min, Math.min(max, v));
}

function easeOutCubic(t) {
	const p = 1 - t;
	return 1 - (p * p * p);
}

function isYellowish(r, g, b) {
	return r >= 170 && g >= 150 && b <= 120;
}

function isEyeYellowGreen(r, g, b) {
	return r >= 150 && g >= 160 && b <= 140;
}

function whenImageReady(img, cb) {
	if (img && img.complete && img.naturalWidth) {
		cb();
		return;
	}
	if (!img) return;
	img.addEventListener("load", cb, { once: true });
}

function randomRainChar() {
	return RAIN_CHARS[(Math.random() * RAIN_CHARS.length) | 0];
}

function setupRain() {
	rainCanvas = document.getElementById("rain");
	if (!rainCanvas) return;
	rainCtx = rainCanvas.getContext("2d");
	resizeRain();
	window.addEventListener("resize", resizeRain);
	requestAnimationFrame(renderRain);
}

function resizeRain() {
	if (!rainCanvas || !rainCtx) return;
	const dpr = Math.max(1, Math.min(3, window.devicePixelRatio || 1));
	const w = Math.max(1, window.innerWidth);
	const h = Math.max(1, window.innerHeight);

	rainCanvas.width = Math.floor(w * dpr);
	rainCanvas.height = Math.floor(h * dpr);
	rainCanvas.style.width = w + "px";
	rainCanvas.style.height = h + "px";
	rainCtx.setTransform(dpr, 0, 0, dpr, 0, 0);

	const cols = Math.max(1, Math.floor(w / RAIN_FONT_PX));
	const next = new Array(cols);

	for (let i = 0; i < cols; i++) {
		const prev = rainColumns[i];
		next[i] = prev || {
			x: i * RAIN_FONT_PX,
			y: -Math.random() * h,
			speed: 35 + Math.random() * 95,
			trail: 12 + ((Math.random() * 24) | 0),
			symbols: [],
			lastHeadRow: -999999,
			changeEveryMs: 160 + ((Math.random() * 260) | 0),
			nextChangeAt: 0
		};

		next[i].x = i * RAIN_FONT_PX;
		if (!next[i].symbols.length) {
			for (let k = 0; k < next[i].trail; k++) next[i].symbols.push(randomRainChar());
		}
	}

	rainColumns = next;
	rainCtx.fillStyle = "rgb(" + RAIN_BG.r + "," + RAIN_BG.g + "," + RAIN_BG.b + ")";
	rainCtx.fillRect(0, 0, w, h);
}

function renderRain(ts) {
	if (!rainCtx || !rainCanvas) return;
	const w = Math.max(1, window.innerWidth);
	const h = Math.max(1, window.innerHeight);
	const dt = rainLastTs ? Math.min(0.05, (ts - rainLastTs) / 1000) : 0;
	rainLastTs = ts;

	rainCtx.fillStyle = "rgba(" + RAIN_BG.r + "," + RAIN_BG.g + "," + RAIN_BG.b + "," + RAIN_FADE_ALPHA + ")";
	rainCtx.fillRect(0, 0, w, h);

	rainCtx.font = RAIN_FONT_PX + "px monospace";
	rainCtx.textBaseline = "top";

	for (let i = 0; i < rainColumns.length; i++) {
		const col = rainColumns[i];

		col.y += col.speed * dt;
		const headRow = Math.floor(col.y / RAIN_FONT_PX);

		if (headRow > col.lastHeadRow) {
			const steps = Math.min(8, headRow - col.lastHeadRow);
			for (let s = 0; s < steps; s++) {
				col.symbols.unshift(randomRainChar());
				if (col.symbols.length > col.trail) col.symbols.pop();
			}
			col.lastHeadRow = headRow;
		}

		if (ts >= col.nextChangeAt) {
			col.nextChangeAt = ts + col.changeEveryMs;
			const changes = 1 + ((Math.random() * 2) | 0);
			for (let c = 0; c < changes; c++) {
				const idx = (Math.random() * col.symbols.length) | 0;
				col.symbols[idx] = randomRainChar();
			}
		}

		for (let t = 0; t < col.symbols.length; t++) {
			const row = headRow - t;
			if (row < 0) break;
			const y = row * RAIN_FONT_PX;
			if (y > h + RAIN_FONT_PX) continue;

			const isHead = t === 0;
			const k = 1 - t / col.symbols.length;
			const a = isHead ? 0.95 : (0.05 + 0.55 * k);
			rainCtx.fillStyle = "rgba(" + RAIN_COLOR.r + "," + RAIN_COLOR.g + "," + RAIN_COLOR.b + "," + a + ")";
			rainCtx.fillText(col.symbols[t], col.x, y);
		}

		if (col.y - col.trail * RAIN_FONT_PX > h + RAIN_FONT_PX) {
			col.y = -Math.random() * h;
			col.speed = 35 + Math.random() * 95;
			col.trail = 12 + ((Math.random() * 24) | 0);
			col.symbols = [];
			for (let k = 0; k < col.trail; k++) col.symbols.push(randomRainChar());
			col.lastHeadRow = Math.floor(col.y / RAIN_FONT_PX);
			col.changeEveryMs = 160 + ((Math.random() * 260) | 0);
			col.nextChangeAt = ts + col.changeEveryMs;
		}
	}

	requestAnimationFrame(renderRain);
}

function scatterParticles() {
	if (!particles.length || !imgW || !imgH) return;
	for (let i = 0, j = particles.length; i < j; i++) {
		const p = particles[i];
		const vx = p.tx - imgCx;
		const vy = p.ty - imgCy;
		const radial = 0.55 + Math.random() * 1.15;
		const scatterX = (Math.random() - 0.5) * imgW * 1.35;
		const scatterY = (Math.random() - 0.5) * imgH * 1.35;
		const sx = p.tx + vx * radial + scatterX;
		const sy = p.ty + vy * radial + scatterY;
		p.sx = sx;
		p.sy = sy;
		p.x = sx;
		p.y = sy;
	}
	animStartTs = 0;
	lastTs = 0;
}

function rebuildFromImage(img, animate) {
	if (!img || !(img.complete && img.naturalWidth)) return;
	currentAvatarImage = img;
	buildParticles(img);
	if (animate) {
		animStartTs = 0;
	} else {
		animStartTs = -1000000000;
	}
	lastTs = 0;
}

window.StarkaidAvatar = {
	setSpeaking(value) {
		speaking = !!value;
		if (!speaking) {
			audioLevel = 0;
			pulseKick = 0;
		}
	},
	setAudioLevel(value) {
		const v = Number(value);
		if (Number.isFinite(v)) audioLevel = Math.max(0, Math.min(100, v));
	},
	beat() {
		pulseKick = 1;
	},
	restartReconstruction() {
		scatterParticles();
	},
	setSleeping(value) {
		const isSleeping = !!value;
		const next = isSleeping ? pngDormindo : png;
		if (currentAvatarImage === next) return;
		whenImageReady(next, () => rebuildFromImage(next, false));
	},
	init() {
		if (png.complete) {
			rebuildFromImage(png, true);
			setupRain();
			requestAnimationFrame(render);
		} else {
			png.onload = function () {
				rebuildFromImage(png, true);
				setupRain();
				requestAnimationFrame(render);
			};
		}
	}
};

function buildParticles(img) {
	canvas = document.getElementById("scene");
	ctx = canvas.getContext("2d");

	canvas.width = img.width * SCALE;
	canvas.height = img.height * SCALE;

	ctx.drawImage(img, 0, 0);
	const data = ctx.getImageData(0, 0, img.width, img.height);
	ctx.clearRect(0, 0, canvas.width, canvas.height);

	const w = img.width;
	const h = img.height;
	const cx = w * 0.5;
	const cy = h * 0.5;

	imgW = w;
	imgH = h;
	imgCx = cx;
	imgCy = cy;

	particles = [];
	for (let y = 0; y < data.height; y += DENSITY) {
		for (let x = 0; x < data.width; x += DENSITY) {
			if (data.data[(y * 4 * data.width) + (x * 4) + 3] > 128) {
				const i = (y * 4 * data.width) + (x * 4);

				const tx = x;
				const ty = y;
				const vx = tx - cx;
				const vy = ty - cy;
				const radial = 0.55 + Math.random() * 1.15;
				const scatterX = (Math.random() - 0.5) * w * 1.35;
				const scatterY = (Math.random() - 0.5) * h * 1.35;
				const sx = tx + vx * radial + scatterX;
				const sy = ty + vy * radial + scatterY;

				particles.push({
					x: sx,
					y: sy,
					sx: sx,
					sy: sy,
					tx: tx,
					ty: ty,
					r: data.data[i],
					g: data.data[i + 1],
					b: data.data[i + 2],
					isReactor: false,
					isEye: false
				});
			}
		}
	}

	const reactorCandidates = [];

	for (let i = 0, j = particles.length; i < j; i++) {
		const p = particles[i];
		const x = p.tx;
		const y = p.ty;

		if (isYellowish(p.r, p.g, p.b) && y > h * 0.55 && Math.abs(x - cx) < w * 0.22) {
			reactorCandidates.push(p);
		}

		;
	}

	if (reactorCandidates.length > 0) {
		let sumX = 0;
		let sumY = 0;
		for (let i = 0, j = reactorCandidates.length; i < j; i++) {
			sumX += reactorCandidates[i].tx;
			sumY += reactorCandidates[i].ty;
		}
		reactorX = sumX / reactorCandidates.length;
		reactorY = sumY / reactorCandidates.length;

		const dists = new Array(reactorCandidates.length);
		for (let i = 0, j = reactorCandidates.length; i < j; i++) {
			const dx = reactorCandidates[i].tx - reactorX;
			const dy = reactorCandidates[i].ty - reactorY;
			dists[i] = Math.sqrt(dx * dx + dy * dy);
		}
		dists.sort((a, b) => a - b);
		reactorR = clamp(dists[Math.floor(dists.length * 0.86)] || (w * 0.07), w * 0.03, w * 0.13);
	} else {
		reactorX = w * 0.5;
		reactorY = h * 0.72;
		reactorR = w * 0.08;
	}

	const reactorR2 = reactorR * reactorR;
	for (let i = 0, j = particles.length; i < j; i++) {
		const p = particles[i];
		const dxr = p.tx - reactorX;
		const dyr = p.ty - reactorY;
		p.isReactor = (dxr * dxr + dyr * dyr) <= reactorR2;
		p.isEye =
			isEyeYellowGreen(p.r, p.g, p.b) &&
			p.ty >= h * 0.18 &&
			p.ty <= h * 0.34 &&
			p.tx >= w * 0.28 &&
			p.tx <= w * 0.72;
	}
}

function render(ts) {
	if (!ctx || !canvas) return;

	if (!animStartTs) animStartTs = ts;

	const dt = lastTs ? Math.min(0.05, (ts - lastTs) / 1000) : 0;
	lastTs = ts;

	if (pulseKick > 0) {
		pulseKick = Math.max(0, pulseKick - dt * 2.8);
	}

	// Audio level handling with simulation for speech pulsing
	let levelAmp = Math.max(0, Math.min(1, audioLevel / 70));

	// Simulate organic pulse if speaking but audioLevel is 0 (or very low)
	if (speaking && levelAmp < 0.05) {
		// Combine sine wave with random jitter for "talking" look
		const sim = 0.35 + 0.25 * Math.sin(ts * 0.015) + (Math.random() * 0.15);
		levelAmp = sim;
	}

	const amp = speaking ? Math.max(levelAmp, pulseKick) : 0;
	const wave = 0.5 + 0.5 * Math.sin(ts / 75);

	const buildT = clamp((ts - animStartTs) / BUILD_DURATION_MS, 0, 1);
	const buildK = easeOutCubic(buildT);

	ctx.clearRect(0, 0, canvas.width, canvas.height);
	for (let i = 0, j = particles.length; i < j; i++) {
		const p = particles[i];
		if (buildK < 1) {
			p.x = p.sx + (p.tx - p.sx) * buildK;
			p.y = p.sy + (p.ty - p.sy) * buildK;
		} else {
			p.x = p.tx;
			p.y = p.ty;
		}

		if (amp > 0 && (p.isReactor || p.isEye)) {
			const base = p.isReactor ? 0.55 : 0.45;
			const alpha = clamp((base + 0.55 * amp) * (0.65 + 0.35 * wave), 0, 1);
			ctx.fillStyle = "rgba(249,253,197," + alpha + ")";
		} else {
			const a = buildT < 1 ? (0.2 + 0.8 * buildT) : 1;
			ctx.fillStyle = "rgba(" + p.r + "," + p.g + "," + p.b + "," + a + ")";
		}
		ctx.fillRect(p.x * SCALE, p.y * SCALE, DOT_SIZE, DOT_SIZE);
	}

	requestAnimationFrame(render);
}

const png = new Image();
png.onload = function () {
	// Auto-init removed. Waiting for StarkaidAvatar.init() to be called by Blazor.
};

png.src = "data:image/png;base64,"

const pngDormindo = new Image();
pngDormindo.src = "data:image/png;base64,"